# ─── 1. Unpack the embedded SDK ───────────────────────────────────────────
step("Unpacking omnia-20x SDK")
root = "/content" if os.path.isdir("/content") else os.getcwd()
zipfile.ZipFile(io.BytesIO(base64.b64decode(SDK_ZIP_B64))).extractall(root)
sdk_dir = next(os.path.join(dp) for dp, dn, fn in os.walk(root)
               if "pyproject.toml" in fn and "omnia_sdk" in dn)
print("  SDK at:", sdk_dir)

# ─── 2. Dependencies ──────────────────────────────────────────────────────
step("Installing dependencies")
sh("apt-get", "-qq", "install", "-y", "openslide-tools")
r = sh(sys.executable, "-m", "pip", "install", "-q",
       "numpy", "torch", "torchvision", "pillow", "zstandard",
       "tifffile", "openslide-python")
print("  deps:", "ok" if r.returncode == 0 else r.stderr[-400:])
r = sh(sys.executable, "-m", "pip", "install", "-q", "-e", sdk_dir)
print("  sdk :", "ok" if r.returncode == 0 else r.stderr[-400:])
if r.returncode != 0:
    print("  (continuing via PYTHONPATH — the SDK is pure Python)")

sys.path.insert(0, sdk_dir)
import numpy as np, torch, torch.nn as nn, openslide
from torch.utils.data import Dataset, DataLoader, Subset
from torchvision.models import resnet18
import omnia_sdk
from omnia_sdk.dataset import OmniaDataset

dev = torch.device("cuda" if torch.cuda.is_available() else "cpu")
gpu = torch.cuda.get_device_name() if dev.type == "cuda" else "CPU"
print(f"  omnia_sdk {omnia_sdk.__version__} | torch {torch.__version__} | {gpu}")
if dev.type != "cuda":
    print("\n  !! No GPU. Re-run with --gpu T4 — a CPU result is not meaningful.")

# ─── 3. Slide ─────────────────────────────────────────────────────────────
step("Fetching a public test slide")
SVS = os.path.join(root, "CMU-1.svs")
URL = "https://openslide.cs.cmu.edu/download/openslide-testdata/Aperio/CMU-1.svs"
if not os.path.exists(SVS):
    t0 = time.time(); sh("wget", "-q", "-O", SVS, URL)
    print(f"  downloaded in {time.time()-t0:.0f}s")
sl = openslide.OpenSlide(SVS)
print(f"  {os.path.getsize(SVS)/1e6:.0f} MB · {sl.dimensions[0]}x{sl.dimensions[1]} px · {sl.level_count} levels")
sl.close()

# ─── 4. Convert ───────────────────────────────────────────────────────────
# --min-level 1 drops the 40x level. Required: full resolution needs ~20 GB to
# preload and Colab's free tier gives ~12 GB.
step("Converting .svs to .omnia")
OMNIA = os.path.join(root, "slide.omnia")
t0 = time.time()
r = sh_sdk(sys.executable, "-m", "omnia_sdk.cli", "svs-convert", SVS, OMNIA,
           "--batch-size", "16", "--zstd-level", "5", "--min-level", "1")
if r.returncode != 0:
    print(r.stdout[-1500:]); print(r.stderr[-1500:]); sys.exit(1)
print(f"  converted in {time.time()-t0:.0f}s -> {os.path.getsize(OMNIA)/1e6:.1f} MB")

# ─── 5. Benchmark ─────────────────────────────────────────────────────────
EPOCHS, BATCH, TILE, LEVEL = 4, 64, 256, 1

class SvsTiles(Dataset):
    """The status quo: openslide decodes JPEG-2000 during training, every epoch."""
    def __init__(self, path):
        self.path, self.s = path, None
        sl = openslide.OpenSlide(path)
        w, h = sl.level_dimensions[LEVEL]; self.ds = sl.level_downsamples[LEVEL]; sl.close()
        self.tx, self.ty = (w + TILE - 1)//TILE, (h + TILE - 1)//TILE
    def __len__(self): return self.tx * self.ty
    def __getitem__(self, i):
        # Handle opened lazily so it survives DataLoader worker forking.
        if self.s is None: self.s = openslide.OpenSlide(self.path)
        x = int((i % self.tx) * TILE * self.ds); y = int((i // self.tx) * TILE * self.ds)
        a = np.asarray(self.s.read_region((x, y), LEVEL, (TILE, TILE)).convert("RGB"))
        return torch.from_numpy(a.copy()).permute(2, 0, 1).float()/255.0, 0

def run(ds, label):
    m = resnet18(weights=None); m.fc = nn.Linear(512, 2); m = m.to(dev).train()
    opt = torch.optim.SGD(m.parameters(), lr=0.01); crit = nn.CrossEntropyLoss()
    dl = DataLoader(ds, batch_size=BATCH, shuffle=True, num_workers=0,
                    pin_memory=(dev.type == "cuda"))
    eps, dts = [], []
    for e in range(EPOCHS):
        if dev.type == "cuda": torch.cuda.synchronize()
        t0 = time.perf_counter(); data_t = 0.0; it = iter(dl)
        while True:
            td = time.perf_counter()
            try: x, y = next(it)
            except StopIteration: break
            data_t += time.perf_counter() - td
            x = x.to(dev, non_blocking=True); y = torch.as_tensor(y).to(dev)
            opt.zero_grad(); crit(m(x), y).backward(); opt.step()
        if dev.type == "cuda": torch.cuda.synchronize()
        tot = time.perf_counter() - t0
        eps.append(tot); dts.append(data_t)
        print(f"  {label} epoch {e+1}: {tot:7.2f}s   data {data_t:6.2f}s ({data_t/tot*100:5.1f}%)", flush=True)
    # Epoch 1 is discarded on both sides so neither is charged for warm-up.
    return float(np.mean(eps[1:])), float(np.mean(dts[1:])), eps[1:]

step("Preloading .omnia into RAM")
t0 = time.time(); ds_om = OmniaDataset(OMNIA, cache_mode="ram"); preload = time.time() - t0
print(f"  {len(ds_om)} tiles in {preload:.1f}s")

# Same tile count both sides, or the comparison means nothing.
svs_full = SvsTiles(SVS)
N = min(len(ds_om), len(svs_full))
step(f"Benchmarking {N} tiles/epoch, {EPOCHS} epochs, batch {BATCH}")
svs_ep, svs_dt, svs_eps = run(Subset(svs_full, range(N)), ".svs  ")
print()
om_ep, om_dt, om_eps = run(Subset(ds_om, range(N)), ".omnia")

# ─── 6. Report ────────────────────────────────────────────────────────────
# CUDA is asynchronous: forward/backward queue work and return immediately, so
# on the slow-data side the GPU drains its queue during the decode wait and the
# measured "compute" collapses toward zero. The per-epoch data/compute split is
# therefore not comparable across the two sides, and an Amdahl ceiling computed
# from it is wrong (it read 42x when the achievable figure was ~4x).
#
# The trustworthy quantities are the synchronised epoch totals and the compute
# floor measured on the fast-data side, where the CPU genuinely waits on the
# GPU. True ceiling = slow epoch / that floor.
compute_floor = om_ep - om_dt
share = svs_dt / svs_ep
ceiling = svs_ep / compute_floor if compute_floor > 0 else float("inf")
e2e = svs_ep / om_ep
dspeed = svs_dt / om_dt if om_dt > 0 else float("inf")
regime = "DATA-BOUND" if e2e >= 10 else ("MIXED" if e2e >= 2 else "MODEL-BOUND")
# Reliability is about run-to-run stability, not the CUDA-distorted split.
def _stable(xs):
    return (max(xs) - min(xs)) / max(xs) < 0.15 if xs else False
stable = _stable(svs_eps) and _stable(om_eps)

print("\n" + "=" * 64)
print(f"  omnia-20x BENCHMARK   ·  {gpu}")
print("=" * 64)
print(f"  tiles/epoch            : {N}")
print(f"  .svs   epoch           : {svs_ep:7.2f}s   (data {svs_dt:6.2f}s = {share*100:.1f}%)")
print(f"  .omnia epoch           : {om_ep:7.2f}s   (data {om_dt:6.2f}s = {om_dt/om_ep*100:.1f}%)")
print("-" * 64)
print(f"  DATA LOADING           : {dspeed:7.1f}x faster")
print(f"  END-TO-END TRAINING    : {e2e:7.2f}x faster      <-- the real answer")
print(f"  GPU compute floor      : {compute_floor:7.2f}s/epoch (measured where the CPU waits on the GPU)")
print(f"  achievable ceiling     : {ceiling:7.2f}x  (epoch / compute floor)")
print(f"  achieved of ceiling    : {e2e/ceiling*100:6.1f}%")
print(f"  regime                 : {regime}")
print("-" * 64)
print(f"  .svs  on disk          : {os.path.getsize(SVS)/1e6:7.1f} MB")
print(f"  .omnia on disk         : {os.path.getsize(OMNIA)/1e6:7.1f} MB")
print(f"  preload (one-off)      : {preload:7.1f}s")
if svs_ep > om_ep:
    print(f"  pays for itself after  : {preload/(svs_ep-om_ep):7.1f} epochs")
print("=" * 64)

if not stable:
    print(f"\n  !! UNRELIABLE: epoch times varied more than 15% within a run")
    print("     Raise EPOCHS or use a bigger slide, then re-run.")
elif share < 0.5:
    print(f"\n  Data loading was only {share*100:.0f}% of the epoch, so the ceiling is")
    print(f"  {ceiling:.1f}x no matter how fast the container is. The GPU is the")
    print("  bottleneck on this machine, not I/O.")
else:
    print(f"\n  Data loading was {share*100:.0f}% of the epoch — the case omnia-20x is")
    print(f"  built for. {(1-om_dt/svs_dt)*100:.0f}% of that cost is now gone.")
